"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[82399],{16343:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>s,default:()=>c,frontMatter:()=>o,metadata:()=>r,toc:()=>d});var a=n(31085),h=n(71184);const o={sidebar_position:12,slug:"/bible/1_Machabees/1_Machabees_12",title:"1 Machabees 12",hide_table_of_contents:!0},s="1 Machabees",r={id:"bible/1 Machabees/1 Machabees 12",title:"1 Machabees 12",description:"Chapter 12",source:"@site/docs/bible/1 Machabees/1 Machabees 12.md",sourceDirName:"bible/1 Machabees",slug:"/bible/1_Machabees/1_Machabees_12",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_12",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Machabees/1 Machabees 12.md",tags:[],version:"current",sidebarPosition:12,frontMatter:{sidebar_position:12,slug:"/bible/1_Machabees/1_Machabees_12",title:"1 Machabees 12",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Machabees 11",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_11"},next:{title:"1 Machabees 13",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_13"}},i={},d=[{value:"Chapter 12",id:"chapter-12",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"1-machabees",children:"1 Machabees"}),"\n",(0,a.jsx)(t.h2,{id:"chapter-12",children:"Chapter 12"}),"\n",(0,a.jsx)(t.p,{children:"Jonathan renews his league with the Romans and Lacedemonians.  The forces of Demetrius flee away from him.  He is deceived and made prisoner by Tryphon."}),"\n",(0,a.jsx)(n,{verse:1,children:"And Jonathan saw that the time served him, and he chose certain men, and sent them to Rome, to confirm and to renew the amity with them:"}),"\n",(0,a.jsx)(n,{verse:2,children:"And he sent letters to the Spartans, and to other places, according to the same form."}),"\n",(0,a.jsx)(n,{verse:3,children:"And they went to Rome, and entered into the senate house, and said: Jonathan, the high priest, and the nation of the Jews, have sent us to renew the amity, and alliance, as it was before."}),"\n",(0,a.jsx)(n,{verse:4,children:"And they gave them letters to their governors in every place, to conduct them into the land of Juda with peace."}),"\n",(0,a.jsx)(n,{verse:5,children:"And this is a copy of the letters which Jonathan wrote to the Spartans:"}),"\n",(0,a.jsx)(n,{verse:6,children:"Jonathan, the high priest, and the ancients of the nation, and the priests, and the rest of the people of the Jews, to the Spartans, their brethren, greeting."}),"\n",(0,a.jsx)(n,{verse:7,children:"There were letters sent long ago to Onias the high priest, from Arius, who reigned then among you to signify that you are our brethren, as the copy here underwritten doth specify."}),"\n",(0,a.jsx)(n,{verse:8,children:"And Onias received the ambassador with honour and received the letters, wherein there was mention made of the alliance, and amity."}),"\n",(0,a.jsx)(n,{verse:9,children:"We, though we needed none of these things having for our comfort the holy books that are in our hands,"}),"\n",(0,a.jsx)(n,{verse:10,children:"Chose rather to send to you to renew the brotherhood and friendship, lest we should become stranger to you altogether: for there is a long time passed since you sent to us."}),"\n",(0,a.jsx)(n,{verse:11,children:"We, therefore, at all times without ceasing, both in our festivals, and other days wherein it is convenient, remember you in the sacrifices that we offer, and in our observances, as it is meet and becoming to remember brethren."}),"\n",(0,a.jsx)(n,{verse:12,children:"And we rejoice at your glory."}),"\n",(0,a.jsx)(n,{verse:13,children:"But we have had many troubles and wars on every side; and the kings that are round about us have fought against us."}),"\n",(0,a.jsx)(n,{verse:14,children:"But we would not be troublesome to you, nor to the rest of our allies and friends, in these wars."}),"\n",(0,a.jsx)(n,{verse:15,children:"For we have had help from heaven, and we have been delivered, and our enemies are humbled."}),"\n",(0,a.jsx)(n,{verse:16,children:"We have chosen, therefore, Numenius the son of Antiochus, and Antipater, the son of Jason, and have sent them to the Romans, to renew with them the former amity and alliance."}),"\n",(0,a.jsx)(n,{verse:17,children:"And we have commanded them to go also to you, and salute you, and to deliver you our letters, concerning the renewing of our brotherhood."}),"\n",(0,a.jsx)(n,{verse:18,children:"And now you shall do well to give us an answer hereto."}),"\n",(0,a.jsx)(n,{verse:19,children:"And this is the copy of the letter which he had sent to Onias:"}),"\n",(0,a.jsx)(n,{verse:20,children:"Arius, king of the Spartans, to Onias, the high priest, greeting."}),"\n",(0,a.jsx)(n,{verse:21,children:"It is found in writing concerning the Spartans, and the Jews, that they are brethren, and that they are of the stock of Abraham."}),"\n",(0,a.jsx)(n,{verse:22,children:"And now since this is come to our knowledge, you do well to write to us of your prosperity."}),"\n",(0,a.jsx)(n,{verse:23,children:"And we also have written back to you, That our cattle, and our possessions, are yours: and yours, ours. We, therefore, have commanded that these things should be told you."}),"\n",(0,a.jsx)(n,{verse:24,children:"Now Jonathan heard that the generals of Demetrius were come again with a greater army than before to fight against him."}),"\n",(0,a.jsx)(n,{verse:25,children:"So he went out from Jerusalem, and met them in the land of Amath: for he gave them no time to enter into his country."}),"\n",(0,a.jsx)(n,{verse:26,children:"And he sent spies into their camp, and they came back, and brought him word that they designed to come upon them in the night."}),"\n",(0,a.jsx)(n,{verse:27,children:"And when the sun was set, Jonathan commanded his men to watch, and to be in arms all night long ready to fight, and he set sentinels round about the camp."}),"\n",(0,a.jsx)(n,{verse:28,children:"And the enemies heard that Jonathan and his men were ready for battle: and they were struck with fear and dread in their heart: and they kindled fires in their camp."}),"\n",(0,a.jsx)(n,{verse:29,children:"But Jonathan, and they that were with him, knew it not till the morning: for they saw the lights burning."}),"\n",(0,a.jsx)(n,{verse:30,children:"And Jonathan pursued after them, but overtook them not: for they had passed the river Eleutherus."}),"\n",(0,a.jsx)(n,{verse:31,children:"And Jonathan turned upon the Arabians, that are called Zabadeans: and he defeated them, and took the spoils of them."}),"\n",(0,a.jsx)(n,{verse:32,children:"And he went forward, and came to Damascus, and passed through all that country."}),"\n",(0,a.jsx)(n,{verse:33,children:"Simon also went forth, and came as far as Ascalon, and the neighbouring fortresses, and he turned aside to Joppe, and took possession of it,"}),"\n",(0,a.jsx)(n,{verse:34,children:"(For he heard that they designed to deliver the hold to them that took part with Demetrius) and he put a garrison there to keep it."}),"\n",(0,a.jsx)(n,{verse:35,children:"And Jonathan came back, and called together the ancients of the people; and he took a resolution with them to build fortresses in Judea,"}),"\n",(0,a.jsx)(n,{verse:36,children:"And to build up walls in Jerusalem, and raise a mount between the castle and the city, to separate it from the city, that so it might have no communication, and that they might neither buy nor sell."}),"\n",(0,a.jsx)(n,{verse:37,children:"And they came together to build up the city: for the wall that was upon the brook, towards the east, was broken down, and he repaired that which is called Caphetetha:"}),"\n",(0,a.jsx)(n,{verse:38,children:"And Simon built Adiada in Sephela, and fortified it, and set up gates and bars."}),"\n",(0,a.jsx)(n,{verse:39,children:"Now when Tryphon had conceived a design to make himself king of Asia and to take the crown, and to stretch out his hand against king Antiochus:"}),"\n",(0,a.jsx)(n,{verse:40,children:"Fearing lest Jonathan would not suffer him, but would fight against him: he sought to seize upon him, and to kill him. So he rose up and came to Bethsan."}),"\n",(0,a.jsx)(n,{verse:41,children:"And Jonathan went out to meet him with forty thousand men chosen for battle, and came to Bethsan."}),"\n",(0,a.jsx)(n,{verse:42,children:"Now when Tryphon saw that Jonathan came with a great army, he durst not stretch forth his hand against him."}),"\n",(0,a.jsx)(n,{verse:43,children:"But received him with honour, and commended him to all his friends, and gave him presents: and he commanded his troops to obey him, as himself."}),"\n",(0,a.jsx)(n,{verse:44,children:"And he said to Jonathan: Why hast thou troubled all the people, whereas we have no war?"}),"\n",(0,a.jsx)(n,{verse:45,children:"Now, therefore, send them back to their own houses: and choose thee a few men that may be with thee, and come with me to Ptolemais, and I will deliver it to thee, and the rest of the strong holds, and the army, and all that have any charge, and I will return and go away: for this is the cause of my coming."}),"\n",(0,a.jsx)(n,{verse:46,children:"And Jonathan believed him, and did as he said: and sent away his army, and they departed into the land of Juda:"}),"\n",(0,a.jsx)(n,{verse:47,children:"But he kept with him three thousand men: of whom he sent two thousand into Galilee, and one thousand went with him."}),"\n",(0,a.jsx)(n,{verse:48,children:"Now as soon as Jonathan entered into Ptolemais, they of Ptolemais shut the gates of the city, and took him: and all them that came in with him they slew with the sword."}),"\n",(0,a.jsx)(n,{verse:49,children:"Then Tryphon sent an army and horsemen into Galilee, and into the great plain, to destroy all Jonathan's company."}),"\n",(0,a.jsx)(n,{verse:50,children:"But they, when they understood that Jonathan, and all that were with him, were taken and slain, encouraged one another, and went out ready for battle."}),"\n",(0,a.jsx)(n,{verse:51,children:"Then they that had come after them, seeing that they stood for their lives, returned back."}),"\n",(0,a.jsx)(n,{verse:52,children:"Whereupon they all came peaceably into the land of Juda and they bewailed Jonathan, and them that had been with him, exceedingly: and Israel mourned with great lamentation."}),"\n",(0,a.jsx)(n,{verse:53,children:"Then all the heathens that were round about them, sought to destroy them. For they said:"}),"\n",(0,a.jsx)(n,{verse:54,children:"They have no prince, nor any to help them: now therefore, let us make war upon them, and take away the memory of them from amongst men."})]})}function c(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var a=n(14041);const h={},o=a.createContext(h);function s(e){const t=a.useContext(o);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);